#!/usr/bin/env python3
import sys, threading
sys.set_int_max_str_digits(0)
sys.setrecursionlimit(10**7)

class PErr(Exception): pass
class TErr(Exception): pass
class RErr(Exception): pass

KW = {'let','rec','in','if','then','else','match','with','type','forall'}
WS = ' \t\n\r\f\v'

def lex(s):
    toks = []; i = 0; n = len(s)
    for ch in s:
        if ord(ch) > 127: raise PErr()
    while i < n:
        c = s[i]
        if c in WS: i += 1; continue
        if c == '-' and s.startswith('--', i):
            j = s.find('\n', i)
            i = n if j < 0 else j
            continue
        if c.isdigit():
            j = i
            while j < n and s[j].isdigit(): j += 1
            toks.append(('INT', int(s[i:j]))); i = j; continue
        if c.isalpha() or c == '_':
            j = i
            while j < n and (s[j].isalnum() or s[j] == '_'): j += 1
            w = s[i:j]; i = j
            if c.isupper():
                if w in ('True','False','Int','Bool'): toks.append((w, None))
                else: raise PErr()
            elif w == '_': raise PErr()
            elif w in KW:
                if w in ('match','with','type','forall'): raise PErr()
                toks.append((w, None))
            else: toks.append(('ID', w))
            continue
        two = s[i:i+2]
        if two in ('//', '->', '=='):
            toks.append((two, None)); i += 2; continue
        if c in '()/+-*%<=:':
            toks.append((c, None)); i += 1; continue
        raise PErr()
    toks.append(('EOF', None))
    return toks

# AST: tuples
# ('int',n) ('bool',b) ('var',x) ('lam',x,e) ('app',f,a) ('op',o,a,b) ('if',c,t,e)
# ('anno',e,T) ('let',x,T|None,e1,e2) ('rec',f,T,x,body,e2)

class Parser:
    def __init__(s, toks): s.t = toks; s.p = 0
    def peek(s): return s.t[s.p][0]
    def next(s):
        t = s.t[s.p]; s.p += 1; return t
    def eat(s, k):
        if s.t[s.p][0] != k: raise PErr()
        return s.next()
    def program(s):
        e = s.expr(); s.eat('EOF'); return e
    def expr(s):
        k = s.peek()
        if k == '/':
            s.next(); x = s.eat('ID')[1]; s.eat('->'); return ('lam', x, s.expr())
        if k == 'if':
            s.next(); c = s.expr(); s.eat('then'); a = s.expr(); s.eat('else'); b = s.expr()
            return ('if', c, a, b)
        if k == 'let':
            s.next()
            if s.peek() == 'rec':
                s.next(); f = s.eat('ID')[1]; s.eat(':'); T = s.type(); s.eat('=')
                depth = 0
                while s.peek() == '(':
                    s.next(); depth += 1
                if s.peek() != '/': raise PErr()
                s.next(); x = s.eat('ID')[1]; s.eat('->'); body = s.expr()
                for _ in range(depth): s.eat(')')
                s.eat('in'); e2 = s.expr()
                return ('rec', f, T, x, body, e2)
            x = s.eat('ID')[1]; T = None
            if s.peek() == ':': s.next(); T = s.type()
            s.eat('='); e1 = s.expr(); s.eat('in'); e2 = s.expr()
            return ('let', x, T, e1, e2)
        return s.cmp()
    def cmp(s):
        a = s.add()
        if s.peek() in ('==', '<'):
            o = s.next()[0]; b = s.add(); a = ('op', o, a, b)
            if s.peek() in ('==', '<'): raise PErr()
        return a
    def add(s):
        a = s.mul()
        while s.peek() in ('+', '-'):
            o = s.next()[0]; a = ('op', o, a, s.mul())
        return a
    def mul(s):
        a = s.app()
        while s.peek() in ('*', '//', '%'):
            o = s.next()[0]; a = ('op', o, a, s.app())
        return a
    ATOM = ('ID', 'INT', 'True', 'False', '(')
    def app(s):
        a = s.atom()
        while s.peek() in Parser.ATOM:
            a = ('app', a, s.atom())
        return a
    def atom(s):
        k, v = s.next()
        if k == 'ID': return ('var', v)
        if k == 'INT': return ('int', v)
        if k == 'True': return ('bool', True)
        if k == 'False': return ('bool', False)
        if k == '(':
            e = s.expr()
            if s.peek() == ':':
                s.next(); T = s.type(); s.eat(')'); return ('anno', e, T)
            s.eat(')'); return e
        raise PErr()
    def type(s):
        a = s.tatom()
        if s.peek() == '->':
            s.next(); return ('fn', a, s.type())
        return a
    def tatom(s):
        k, _ = s.next()
        if k == 'Int': return 'Int'
        if k == 'Bool': return 'Bool'
        if k == '(':
            t = s.type(); s.eat(')'); return t
        raise PErr()

# Types: 'Int','Bool',('fn',a,b), Var objects
class TV:
    __slots__ = ('ref',)
    def __init__(s): s.ref = None

def prune(t):
    while isinstance(t, TV) and t.ref is not None: t = t.ref
    return t

def occurs(v, t):
    t = prune(t)
    if t is v: return True
    if isinstance(t, tuple): return occurs(v, t[1]) or occurs(v, t[2])
    return False

def unify(a, b):
    a = prune(a); b = prune(b)
    if a is b: return
    if isinstance(a, TV):
        if occurs(a, b): raise TErr()
        a.ref = b; return
    if isinstance(b, TV): return unify(b, a)
    if isinstance(a, tuple) and isinstance(b, tuple):
        unify(a[1], b[1]); unify(a[2], b[2]); return
    if a != b: raise TErr()

def infer(env, e):
    k = e[0]
    if k == 'int': return 'Int'
    if k == 'bool': return 'Bool'
    if k == 'var':
        if e[1] not in env: raise TErr()
        return env[e[1]]
    if k == 'lam':
        a = TV(); r = infer({**env, e[1]: a}, e[2]); return ('fn', a, r)
    if k == 'app':
        f = infer(env, e[1]); x = infer(env, e[2]); r = TV()
        unify(f, ('fn', x, r)); return r
    if k == 'op':
        unify(infer(env, e[2]), 'Int'); unify(infer(env, e[3]), 'Int')
        return 'Bool' if e[1] in ('==', '<') else 'Int'
    if k == 'if':
        unify(infer(env, e[1]), 'Bool')
        a = infer(env, e[2]); unify(a, infer(env, e[3])); return a
    if k == 'anno':
        unify(infer(env, e[1]), e[2]); return e[2]
    if k == 'let':
        t = infer(env, e[3])
        if e[2] is not None: unify(t, e[2]); t = e[2]
        return infer({**env, e[1]: t}, e[4])
    if k == 'rec':
        env2 = {**env, e[1]: e[2]}
        a = TV(); r = infer({**env2, e[3]: a}, e[4])
        unify(('fn', a, r), e[2])
        return infer(env2, e[5])
    raise TErr()

class Clo:
    __slots__ = ('x', 'body', 'env')
    def __init__(s, x, body, env): s.x = x; s.body = body; s.env = env

def ev(env, e):
    while True:
        k = e[0]
        if k == 'int': return e[1]
        if k == 'var': return env[e[1]]
        if k == 'app':
            f = ev(env, e[1]); a = ev(env, e[2])
            env = f.env.copy(); env[f.x] = a; e = f.body; continue
        if k == 'op':
            a = ev(env, e[2]); b = ev(env, e[3]); o = e[1]
            if o == '+': return a + b
            if o == '-': return a - b
            if o == '*': return a * b
            if o == '<': return a < b
            if o == '==': return a == b
            if b == 0: raise RErr()
            if o == '//': return a // b
            return a % b
        if k == 'if':
            e = e[2] if ev(env, e[1]) else e[3]; continue
        if k == 'let':
            v = ev(env, e[3]); env = env.copy(); env[e[1]] = v; e = e[4]; continue
        if k == 'lam': return Clo(e[1], e[2], env)
        if k == 'bool': return e[1]
        if k == 'anno': e = e[1]; continue
        if k == 'rec':
            env = env.copy(); c = Clo(e[3], e[4], env); env[e[1]] = c; e = e[5]; continue

def main():
    out = None; code = 1
    try:
        with open(sys.argv[2], 'rb') as fh: data = fh.read()
        try: src = data.decode('utf-8')
        except Exception: raise PErr()
        ast = Parser(lex(src)).program()
        infer({}, ast)
        v = ev({}, ast)
        if isinstance(v, bool): out = 'True' if v else 'False'
        elif isinstance(v, int): out = str(v)
        else: out = '<function>'
        code = 0
    except PErr: out = 'ParseError'
    except TErr: out = 'TypeError'
    except RErr: out = 'RuntimeError'
    except RecursionError: out = 'RuntimeError: recursion'
    sys.stdout.write(out + '\n'); sys.stdout.flush()
    os_exit(code)

def os_exit(c):
    import os; os._exit(c)

threading.stack_size(1024 * 1024 * 1024)
t = threading.Thread(target=main); t.start(); t.join()
